import * as net from 'net';
import { createServer as tlsCreateServer } from 'tls';
import { ECONNREFUSED, NO_MESSAGE_HANDLER, TCP_DEFAULT_HOST, TCP_DEFAULT_PORT, } from '../constants.js';
import { TcpContext } from '../ctx-host/tcp.context.js';
import { Transport } from '../enums/index.js';
import { JsonSocket } from '../helpers/index.js';
import { InvalidTcpDataReceptionException } from '../errors/invalid-tcp-data-reception.exception.js';
import { Server } from './server.js';
import { isUndefined } from '@nestjs/common/internal';
/**
 * @publicApi
 */
export class ServerTCP extends Server {
    options;
    transportId = Transport.TCP;
    server;
    port;
    host;
    socketClass;
    maxBufferSize;
    incompleteMessageTimeout;
    maxSendBufferSize;
    isManuallyTerminated = false;
    retryAttemptsCount = 0;
    tlsOptions;
    pendingEventListeners = [];
    /**
     * Sockets accepted by this server that are still open. "net.Server#close"
     * only stops the server from accepting new connections, so these are tracked
     * separately and torn down on "close" - otherwise the process outlives the
     * shutdown and handlers keep running on already established connections.
     */
    openSockets = new Set();
    constructor(options) {
        super();
        this.options = options;
        this.port = this.getOptionsProp(options, 'port', TCP_DEFAULT_PORT);
        this.host = this.getOptionsProp(options, 'host', TCP_DEFAULT_HOST);
        this.socketClass = this.getOptionsProp(options, 'socketClass', JsonSocket);
        this.tlsOptions = this.getOptionsProp(options, 'tlsOptions');
        this.maxBufferSize = this.getOptionsProp(options, 'maxBufferSize');
        this.incompleteMessageTimeout = this.getOptionsProp(options, 'incompleteMessageTimeout');
        this.maxSendBufferSize = this.getOptionsProp(options, 'maxSendBufferSize');
        this.init();
        this.initializeSerializer(options);
        this.initializeDeserializer(options);
    }
    listen(callback) {
        // The once('error') listener outlives a successful listen, so a later
        // error must find the callback already settled.
        let listenCallback = callback;
        const settleListenCallback = (err) => {
            const cb = listenCallback;
            listenCallback = undefined;
            isUndefined(err) ? cb?.() : cb?.(err);
        };
        this.server.once("error" /* TcpEventsMap.ERROR */, err => {
            if (!listenCallback) {
                return;
            }
            this._status$.next("disconnected" /* TcpStatus.DISCONNECTED */);
            settleListenCallback(err);
        });
        this.server.listen(this.port, this.host, () => settleListenCallback());
    }
    close() {
        this.isManuallyTerminated = true;
        this.server.close();
        this.closeOpenSockets();
        this.pendingEventListeners = [];
    }
    bindHandler(socket) {
        this.trackOpenSocket(socket);
        const readSocket = this.getSocketInstance(socket);
        readSocket.on('message', (msg) => this.handleMessage(readSocket, msg).catch(err => this.handleError(err)));
        readSocket.on("error" /* TcpEventsMap.ERROR */, err => {
            const invalidError = new InvalidTcpDataReceptionException(err);
            this.handleError(invalidError);
        });
    }
    async handleMessage(socket, rawMessage) {
        const packet = await this.deserializer.deserialize(rawMessage);
        const pattern = this.getPatternAsString(packet.pattern);
        const tcpContext = new TcpContext([socket, pattern, packet.metadata]);
        if (isUndefined(packet.id)) {
            return this.handleEvent(pattern, packet, tcpContext);
        }
        const handler = this.getHandlerByPattern(pattern);
        if (!handler) {
            const status = 'error';
            const noHandlerPacket = this.serializer.serialize({
                id: packet.id,
                status,
                err: NO_MESSAGE_HANDLER,
            });
            return socket.sendMessage(noHandlerPacket);
        }
        return this.handleRequest(tcpContext, async () => this.transformToObservable(await handler(packet.data, tcpContext)), data => {
            Object.assign(data, { id: packet.id });
            const outgoingResponse = this.serializer.serialize(data);
            socket.sendMessage(outgoingResponse);
        });
    }
    handleClose() {
        if (this.isManuallyTerminated ||
            !this.getOptionsProp(this.options, 'retryAttempts') ||
            this.retryAttemptsCount >=
                this.getOptionsProp(this.options, 'retryAttempts', 0)) {
            return undefined;
        }
        ++this.retryAttemptsCount;
        return setTimeout(() => this.server.listen(this.port, this.host), this.getOptionsProp(this.options, 'retryDelay', 0));
    }
    unwrap() {
        if (!this.server) {
            throw new Error('Not initialized. Please call the "listen"/"startAllMicroservices" method before accessing the server.');
        }
        return this.server;
    }
    on(event, callback) {
        if (this.server) {
            this.server.on(event, callback);
        }
        else {
            this.pendingEventListeners.push({ event, callback });
        }
    }
    init() {
        if (this.tlsOptions) {
            // TLS enabled, use tls server
            this.server = tlsCreateServer(this.tlsOptions, this.bindHandler.bind(this));
        }
        else {
            // TLS disabled, use net server
            this.server = net.createServer(this.bindHandler.bind(this));
        }
        this.registerListeningListener(this.server);
        this.registerErrorListener(this.server);
        this.registerCloseListener(this.server);
        this.pendingEventListeners.forEach(({ event, callback }) => this.server.on(event, callback));
        this.pendingEventListeners = [];
    }
    registerListeningListener(socket) {
        socket.on("listening" /* TcpEventsMap.LISTENING */, () => {
            this._status$.next("connected" /* TcpStatus.CONNECTED */);
        });
    }
    registerErrorListener(socket) {
        socket.on("error" /* TcpEventsMap.ERROR */, err => {
            if ('code' in err && err.code === ECONNREFUSED) {
                this._status$.next("disconnected" /* TcpStatus.DISCONNECTED */);
            }
            this.handleError(err);
        });
    }
    registerCloseListener(socket) {
        socket.on("close" /* TcpEventsMap.CLOSE */, () => {
            this._status$.next("disconnected" /* TcpStatus.DISCONNECTED */);
            this.handleClose();
        });
    }
    /**
     * Keeps a reference to an accepted socket so that it can be destroyed when
     * the server is closed, and drops it again once it closes on its own.
     */
    trackOpenSocket(socket) {
        if (!socket) {
            return;
        }
        this.openSockets.add(socket);
        socket.on("close" /* TcpEventsMap.CLOSE */, () => this.openSockets.delete(socket));
    }
    /**
     * Destroys every socket still open. Called on shutdown so that "close" does
     * not leave the process alive, and so that no further messages are dispatched
     * to handlers over connections established before the shutdown.
     */
    closeOpenSockets() {
        this.openSockets.forEach(socket => socket.destroy());
        this.openSockets.clear();
    }
    getSocketInstance(socket) {
        // Pass the framing options only if socketClass is JsonSocket
        // For custom socket classes, users should handle them in their own implementation
        const hasJsonSocketOptions = this.maxBufferSize !== undefined ||
            this.incompleteMessageTimeout !== undefined ||
            this.maxSendBufferSize !== undefined;
        if (hasJsonSocketOptions && this.socketClass === JsonSocket) {
            return new this.socketClass(socket, {
                maxBufferSize: this.maxBufferSize,
                incompleteMessageTimeout: this.incompleteMessageTimeout,
                maxSendBufferSize: this.maxSendBufferSize,
            });
        }
        return new this.socketClass(socket);
    }
}
